using JobOrbit.Application.DTOs.HiringManagerSettings;using JobOrbit.Application.Interfaces;using JobOrbit.Domain.Enums;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace JobOrbit.API.Controllers;[ApiController,Route("api/managers/me"),Authorize(Roles=nameof(UserRole.HiringManager))]public sealed class HiringManagerSettingsController(IHiringManagerSettingsService service):ControllerBase{bool Id(out int id)=>int.TryParse(User.FindFirst("UserId")?.Value,out id);[HttpGet("settings")]public async Task<ActionResult<HiringManagerSettingsDto>>Get(CancellationToken t)=>Id(out var id)?await service.GetAsync(id,t)is{}x?Ok(x):NotFound():Unauthorized();[HttpPut("settings")]public async Task<ActionResult<HiringManagerSettingsDto>>Update(UpdateHiringManagerSettingsRequest r,CancellationToken t)=>Id(out var id)?await service.UpdateAsync(id,r,t)is{}x?Ok(x):NotFound():Unauthorized();[HttpPut("password")]public async Task<IActionResult>Password(ChangeHiringManagerPasswordRequest r,CancellationToken t){if(!Id(out var id))return Unauthorized();return await service.ChangePasswordAsync(id,r,t)switch{HiringManagerPasswordOutcome.Changed=>NoContent(),HiringManagerPasswordOutcome.IncorrectCurrentPassword=>Unauthorized(new ProblemDetails{Status=401,Title="Current password is incorrect"}),_=>NotFound()};}}
